#!/usr/bin/env python3
"""Fetch selected Paul Graham essays and create an audiobook MP3 via TTS."""

import json
import os
import re
import subprocess
import sys
import html as html_lib
from urllib.request import Request, urlopen
from urllib.error import URLError, HTTPError
from html.parser import HTMLParser
from urllib.parse import urljoin

BASE_URL = "https://www.paulgraham.com/"
ARTICLES_URL = urljoin(BASE_URL, "articles.html")

ESSAYS = [
    "Do Things that don't scale",
    "Founder mode",
]


def http_get(url):
    req = Request(url, headers={"User-Agent": "Mozilla/5.0"})
    with urlopen(req, timeout=30) as resp:
        return resp.read().decode("utf-8", errors="replace")


class LinkParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.current_href = None
        self.current_text = []
        self.links = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "a":
            href = None
            for k, v in attrs:
                if k.lower() == "href":
                    href = v
                    break
            self.current_href = href
            self.current_text = []

    def handle_data(self, data):
        if self.current_href is not None:
            self.current_text.append(data)

    def handle_endtag(self, tag):
        if tag.lower() == "a" and self.current_href is not None:
            text = "".join(self.current_text).strip()
            if text:
                self.links.append((self.current_href, text))
            self.current_href = None
            self.current_text = []


class EssayFontParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.capture = False
        self.skip = False
        self.current = []
        self.segments = []

    def handle_starttag(self, tag, attrs):
        t = tag.lower()
        if t in ("script", "style"):
            self.skip = True
            return
        if t == "font":
            attrs_dict = {k.lower(): v for k, v in attrs}
            if attrs_dict.get("size") == "2" and attrs_dict.get("face", "").lower() == "verdana":
                self.capture = True
                self.current = []
        if self.capture and t in ("br", "p", "div", "tr", "li"):
            self.current.append("\n")

    def handle_endtag(self, tag):
        t = tag.lower()
        if t in ("script", "style"):
            self.skip = False
            return
        if t == "font" and self.capture:
            self.segments.append("".join(self.current))
            self.capture = False
            self.current = []
        if self.capture and t in ("p", "div", "tr", "li"):
            self.current.append("\n")

    def handle_data(self, data):
        if self.capture and not self.skip:
            self.current.append(data)


def normalize_title(s):
    s = s.lower()
    s = re.sub(r"[^a-z0-9]+", " ", s)
    return re.sub(r"\s+", " ", s).strip()


def find_essay_urls():
    html = http_get(ARTICLES_URL)
    parser = LinkParser()
    parser.feed(html)

    target_map = {normalize_title(t): t for t in ESSAYS}
    found = {}

    for href, text in parser.links:
        key = normalize_title(text)
        if key in target_map and key not in found:
            found[key] = urljoin(BASE_URL, href)

    missing = [t for t in ESSAYS if normalize_title(t) not in found]
    if missing:
        raise RuntimeError(f"Could not find essays in index: {missing}")

    return [(target_map[k], found[k]) for k in found]


def extract_essay_text(html):
    parser = EssayFontParser()
    parser.feed(html)
    if not parser.segments:
        raise RuntimeError("No essay text segments found")

    # Choose the longest segment (the essay body).
    segment = max(parser.segments, key=len)
    text = html_lib.unescape(segment)
    text = text.replace("\xa0", " ")
    text = re.sub(r"\r\n?", "\n", text)
    # Normalize line breaks and spaces
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r"\n\s*\n\s*\n+", "\n\n", text)
    text = text.strip()
    return text


def clean_text_for_tts(text):
    text = re.sub(r"http[s]?://\S+", "", text)
    text = re.sub(r"\[\d+\]", "", text)
    text = re.sub(r"\s+", " ", text)
    text = re.sub(r"[^\w\s.,!?;:'\"()\-]", " ", text)
    text = re.sub(r"\s+", " ", text)
    return text.strip()


def chunk_text(text, max_chars=3500):
    sentences = re.split(r"(?<=[.!?])\s+", text)
    chunks = []
    current = ""
    for sentence in sentences:
        if len(current) + len(sentence) + 1 <= max_chars:
            current += sentence + " "
        else:
            if current:
                chunks.append(current.strip())
            current = sentence + " "
    if current.strip():
        chunks.append(current.strip())
    return chunks


def tts_openai(chunks, output_path):
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise RuntimeError("OPENAI_API_KEY not set")

    audio_files = []
    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/pg_chunk_{i:03d}.mp3"
        payload = {
            "model": "tts-1",
            "input": chunk,
            "voice": "onyx",
            "response_format": "mp3",
        }
        data = json.dumps(payload).encode("utf-8")
        req = Request(
            "https://api.openai.com/v1/audio/speech",
            data=data,
            headers={
                "Authorization": f"Bearer {api_key}",
                "Content-Type": "application/json",
            },
            method="POST",
        )
        try:
            with urlopen(req, timeout=60) as resp:
                audio = resp.read()
        except HTTPError as e:
            err = e.read().decode("utf-8", errors="replace")
            raise RuntimeError(f"OpenAI TTS error {e.code}: {err}")
        except URLError as e:
            raise RuntimeError(f"OpenAI TTS connection error: {e}")

        with open(chunk_file, "wb") as f:
            f.write(audio)
        audio_files.append(chunk_file)

    concat_audio(audio_files, output_path)


def concat_audio(audio_files, output_path):
    if not audio_files:
        raise RuntimeError("No audio files to concatenate")

    list_file = "/tmp/pg_audio_list.txt"
    with open(list_file, "w") as f:
        for path in audio_files:
            f.write(f"file '{path}'\n")

    result = subprocess.run(
        ["ffmpeg", "-y", "-f", "concat", "-safe", "0", "-i", list_file, "-c", "copy", output_path],
        capture_output=True,
        text=True,
    )
    if result.returncode != 0:
        raise RuntimeError(f"ffmpeg concat failed: {result.stderr.strip()}")

    for path in audio_files:
        try:
            os.unlink(path)
        except OSError:
            pass
    try:
        os.unlink(list_file)
    except OSError:
        pass


def main():
    try:
        essay_links = find_essay_urls()
    except Exception as e:
        print(f"Error finding essays: {e}", file=sys.stderr)
        sys.exit(1)

    all_text = []
    for title, url in essay_links:
        print(f"Fetching: {title} -> {url}")
        html = http_get(url)
        essay_text = extract_essay_text(html)
        essay_text = clean_text_for_tts(essay_text)
        if len(essay_text) < 1000:
            print(f"Warning: extracted text seems short for {title} ({len(essay_text)} chars)")
        all_text.append(f"{title}. {essay_text}")

    combined = "\n\n".join(all_text)
    chunks = chunk_text(combined, max_chars=3500)
    print(f"Total characters: {len(combined)}; chunks: {len(chunks)}")

    output_path = "/root/audiobook.mp3"
    tts_openai(chunks, output_path)
    print(f"Audiobook created: {output_path}")


if __name__ == "__main__":
    main()
